33	/* Base64 编码函数 */
34	static int base64_encode(FAR const uint8_t *input, size_t input_len,
35	                        FAR char *output, size_t output_size)
36	{
37	  size_t i;
38	  size_t j = 0;
39	  uint32_t n;
40	
41	  if (output_size < ((input_len + 2) / 3) * 4 + 1)
42	    {
43	      return -ENOMEM;
44	    }
45	
46	  for (i = 0; i < input_len; i += 3)
47	    {
48	      n = ((uint32_t)input[i]) << 16;
49	      if (i + 1 < input_len)
50	        {
51	          n |= ((uint32_t)input[i + 1]) << 8;
52	        }
53	      if (i + 2 < input_len)
54	        {
55	          n |= input[i + 2];
56	        }
57	
58	      output[j++] = base64_table[(n >> 18) & 0x3F];
59	      output[j++] = base64_table[(n >> 12) & 0x3F];
60	      output[j++] = (i + 1 < input_len) ? base64_table[(n >> 6) & 0x3F] : '=';
61	      output[j++] = (i + 2 < input_len) ? base64_table[n & 0x3F] : '=';
62	    }
63	
64	  output[j] = '\0';
65	  return j;
66	}
