21	/* 简化的唤醒词检测 - 在实际应用中应该扩展 KWS 模型
22	 * 这里使用离线 KWS 模型的 VOICE_COMMAND_WAKE 类别
23	 */
24	bool voice_recognizer_detect_wake_word(FAR const char *pcm_path,
25	                                       FAR uint16_t *score)
26	{
27	  struct voice_recognition_result_s result;
28	  int ret;
29	
30	  if (pcm_path == NULL || score == NULL)
31	    {
32	      return false;
33	    }
34	
35	  /* 调用现有的 KWS 识别器 */
36	  ret = voice_recognizer_recognize(pcm_path, &result);
37	  if (ret < 0)
38	    {
39	      syslog(LOG_WARNING, "Wake word detection failed: %d\n", ret);
40	      return false;
41	    }
42	
43	  *score = result.score;
44	
45	  /* 检查是否为唤醒词类别 */
46	  if (result.command == VOICE_COMMAND_WAKE && result.score > 180)
47	    {
48	      syslog(LOG_INFO, "Wake word detected! Score: %u\n", result.score);
49	      return true;
50	    }
51	
52	  return false;
53	}
54	
55	/* 判断是否为离线固定指令查询 */
56	static enum voice_command_online_e
57	map_offline_command(enum voice_command_e cmd)
58	{
59	  switch (cmd)
60	    {
61	      case VOICE_COMMAND_QUERY_TEMPERATURE:
62	        return VOICE_COMMAND_ONLINE_QUERY_TEMPERATURE;
63	      case VOICE_COMMAND_QUERY_HUMIDITY:
64	        return VOICE_COMMAND_ONLINE_QUERY_HUMIDITY;
65	      case VOICE_COMMAND_QUERY_LIGHT:
66	        return VOICE_COMMAND_ONLINE_QUERY_LIGHT;
67	      case VOICE_COMMAND_QUERY_AIR_QUALITY:
68	        return VOICE_COMMAND_ONLINE_QUERY_AIR_QUALITY;
69	      case VOICE_COMMAND_WAKE:
70	        return VOICE_COMMAND_ONLINE_WAKE_WORD;
71	      default:
72	        return VOICE_COMMAND_ONLINE_UNKNOWN;
73	    }
74	}
