76	/****************************************************************************
77	 * Public Functions
78	 ****************************************************************************/
79	
80	int voice_recognizer_online_recognize(
81	  FAR const char *pcm_path,
82	  FAR struct mimo_service_s *mimo_service,
83	  bool online_mode,
84	  FAR struct voice_recognition_online_result_s *result)
85	{
86	  struct voice_recognition_result_s offline_result;
87	  int ret;
88	
89	  if (pcm_path == NULL || result == NULL)
90	    {
91	      return -EINVAL;
92	    }
93	
94	  memset(result, 0, sizeof(struct voice_recognition_online_result_s));
95	  result->is_online_mode = online_mode;
96	
97	  /* 步骤 1: 首先用 KWS 检测唤醒词或固定指令 */
98	  ret = voice_recognizer_recognize(pcm_path, &offline_result);
99	  if (ret < 0)
100	    {
101	      syslog(LOG_ERR, "Offline recognition failed: %d\n", ret);
102	      return ret;
103	    }
104	
105	  result->score = offline_result.score;
106	  result->command = map_offline_command(offline_result.command);
107	
108	  /* 检测到唤醒词 */
109	  if (offline_result.command == VOICE_COMMAND_WAKE)
110	    {
111	      result->is_wake_word = true;
112	      result->success = true;
113	      syslog(LOG_INFO, "Wake word detected in online recognizer\n");
114	      return OK;
115	    }
116	
117	  /* 检测到固定指令（温度、湿度、光照、空气质量） */
118	  if (offline_result.command >= VOICE_COMMAND_QUERY_TEMPERATURE &&
119	      offline_result.command <= VOICE_COMMAND_QUERY_AIR_QUALITY)
120	    {
121	      result->success = true;
122	      syslog(LOG_INFO, "Fixed command detected: %d\n", result->command);
123	      return OK;
124	    }
125	
126	  /* 步骤 2: 如果是在线模式且没有识别为固定指令，调用 MiMo */
127	  if (online_mode && mimo_service != NULL &&
128	      mimo_service->config.enabled &&
129	      strlen(mimo_service->config.api_key) > 0)
130	    {
131	      struct mimo_asr_result_s asr_result;
132	      struct mimo_llm_response_s llm_response;
133	
134	      syslog(LOG_INFO, "Using online MiMo for recognition\n");
135	
136	      /* ASR: 语音转文字 */
137	      ret = mimo_asr(mimo_service, pcm_path, &asr_result);
138	      if (ret < 0 || !asr_result.success)
139	        {
140	          syslog(LOG_WARNING, "MiMo ASR failed, falling back to offline\n");
141	          result->command = VOICE_COMMAND_ONLINE_UNKNOWN;
142	          result->success = false;
143	          return -ENODATA;
144	        }
145	
146	      strncpy(result->text, asr_result.text, sizeof(result->text) - 1);
147	      syslog(LOG_INFO, "ASR result: %s\n", result->text);
